seq = ""
for line in open("region.fasta"):
    line=line.strip()
    if line.startswith(">"): continue
    seq += line
seq = seq.upper()

def rc(s):
    return s.translate(str.maketrans("ACGT","TGCA"))[::-1]

def find_orfs(s, strand):
    orfs=[]
    n=len(s)
    for frame in range(3):
        i=frame
        while i < n-2:
            if s[i:i+3]=="ATG":
                j=i
                while j < n-2:
                    cod=s[j:j+3]
                    if cod in ("TAA","TAG","TGA"):
                        orfs.append((i,j+3,j+3-i,strand))
                        break
                    j+=3
                else:
                    orfs.append((i,n,n-i,strand))
                i+=3
            else:
                i+=3
    return orfs

orfs = find_orfs(seq,"+") + find_orfs(rc(seq),"-")
orfs.sort(key=lambda x:-x[2])
print("Top ORFs (start,end,length,strand) 1-based coords for + strand:")
for o in orfs[:15]:
    if o[3]=="+":
        print("+ 1-based %d-%d  len %d aa %d" % (o[0]+1,o[1],o[2],o[2]//3-1))
    else:
        # convert to 1-based on reverse
        st = len(seq)-o[1]+1
        en = len(seq)-o[0]
        print("- 1-based %d-%d  len %d aa %d" % (st,en,o[2],o[2]//3-1))
